def eulerian_num(n, m):
    # Create a table to store the Eulerian numbers
    A = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case
    A[0][0] = 1

    # Fill the table using the correct recursive relation
    for i in range(1, n + 1):
        for j in range(i + 1):
            if j == 0:
                A[i][j] = 1  # A(n, 0) = 1
            elif j == i:
                A[i][j] = 0  # A(n, n) = 0
            else:
                A[i][j] = (j + 1) * A[i - 1][j] + (i - j) * A[i - 1][j - 1]

    return A[n][m] if m <= n else 0  # Return 0 if m > n
