def amicable_numbers_sum(n):
    """Returns the sum of all amicable numbers from 1 to n."""

    if n < 1:
        return 0

    def sum_of_divisors(num):
        total = 1  # Start with 1, as it's a divisor for all numbers > 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:  # Add the complementary divisor
                    total += num // i
        return total

