def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if m < 1 or n < 1:
        raise ValueError("Both m and n must be positive integers.")

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, m + 1):
        dp[1][i] = 1

    for length in range(2, n + 1):
        cumulative_sum = [0] * (m + 1)
        for last in range(1, m + 1):
            cumulative_sum[last] = cumulative_sum[last - 1] + dp[length - 1][last]

        for last in range(1, m + 1):
            start = max(1, (last + 1) // 2)
            end = last
            if start <= end:
                dp[length][last] = cumulative_sum[end] - cumulative_sum[start - 1]

    return sum(dp[n][1:m + 1])
