def max_sub_array_sum_repeated(arr, k):
    if not arr or k <= 0:
        return 0

    # Function to find the maximum subarray sum using Kadane's algorithm
    def kadane(array):
        max_ending_here = max_so_far = array[0]
        for x in array[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Calculate the sum of the original array
    total_sum = sum(arr)

    # Calculate max subarray sum for the original array
    max_kadane = kadane(arr)

    # If k == 1, return the max subarray sum of the original array
    if k == 1:
        return max_kadane

    # Calculate max subarray sum for the array repeated twice
    max_kadane_twice = kadane(arr + arr)

    # If total_sum is positive, we can add it to the result for k-2 full arrays
    if total_sum > 0:
        return max(max_kadane, max_kadane_twice, max_kadane + (k - 2) * total_sum)
    else:
        return max(max_kadane, max_kadane_twice)
