    len1, len2 = len(arr1), len(arr2)

    if k < 1 or k > len1 + len2:
        raise ValueError("k is out of bounds")

    if len1 > len2:
        arr1, arr2, len1, len2 = arr2, arr1, len2, len1

    if len1 == 0:
        return arr2[k - 1]
    if k == 1:
