def find_kth(arr1, arr2, k):
    len1, len2 = len(arr1), len(arr2)

    if k < 1 or k > len1 + len2:
        raise ValueError("k is out of bounds")

    if len1 > len2:
        arr1, arr2, len1, len2 = arr2, arr1, len2, len1

    if len1 == 0:
        return arr2[k - 1]
    if k == 1:
        return min(arr1[0], arr2[0])

    i = min(len1, k // 2)
    j = k - i

    if j > len2:  # Ensure j does not exceed the length of arr2
        return find_kth(arr1, arr2[len2 - (k - len1):], k - len1)

    if arr1[i - 1] < arr2[j - 1]:
        return find_kth(arr1[i:], arr2, k - i)
    else:
        return find_kth(arr1, arr2[j:], k - j)
