def get_total_number_of_sequences(m, n):
    if m <= 0 or n <= 0:
        return 0  # Invalid input case

    # dp[length][last] will store the number of sequences of given length ending with last
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: one way to have a sequence of length 1 for each starting number
    for start in range(1, m + 1):
        dp[1][start] = 1

    for length in range(2, n + 1):
        for last in range(1, m + 1):
            # We can only form a sequence of length 'length' ending with 'last' 
            # if there exists a valid previous number that is at least half of 'last'
            for prev in range((last + 1) // 2, last + 1):
                if prev <= m:
                    dp[length][last] += dp[length - 1][prev]

    # Sum all sequences of length n
    total_sequences = sum(dp[n][last] for last in range(1, m + 1))

    return total_sequences
