def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1  # One sequence of length 0 (the empty sequence)
    if m < 1:
        return 0  # No valid sequences if m is less than 1

    # Dynamic programming table to store the number of sequences
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: one way to have a sequence of length 1 for each number from 1 to m
    for i in range(1, m + 1):
        dp[1][i] = 1

    # Fill the dp table
    for length in range(2, n + 1):
        for last in range(1, m + 1):
            # The previous number must be in the range [last/2, last]
            start = max(1, (last + 1) // 2)
            end = last
            if start <= end:
                dp[length][last] = sum(dp[length - 1][start:end + 1])

    # Sum all sequences of length n
    return sum(dp[n][1:m + 1])
```

